class Solution:
    def findAnagrams(self, s: str, p: str) -> List[int]:
        p_freq, w_freq = [0] * 26, [0] * 26
        res = []
        for ch in p:
            p_freq[ord(ch) - ord('a')] += 1
        left = 0
        for right, ch in enumerate(s):
            w_freq[ord(ch) - ord('a')] += 1
            if right - left + 1 == len(p): # 稳定大小的滑窗写法
                if p_freq == w_freq:
                    res.append(left)
                w_freq[ord(s[left]) - ord('a')] -= 1
                left += 1
        return res
